// frontend/src/components/AdminStudentsFees.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import '../styles/main.css';

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [overrides, setOverrides] = useState({});

  // Fetch all students
  const fetchStudents = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/admissions");
      setStudents(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load students");
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // When admin selects a student
  const selectStudent = async (stu) => {
    setSelected(stu);
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${stu.admissionNo}`);
      if (res.data.success) {
        const fee = res.data.data.fee.items;
        const feeMap = {};
        Object.keys(fee).forEach((key) => (feeMap[key] = fee[key].amount));
        setOverrides(feeMap);
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load fee details");
    }
  };

  // Handle override change
  const updateOverride = (key, value) => {
    setOverrides((prev) => ({ ...prev, [key]: Number(value) }));
  };

  // Save changes
  const saveChanges = async () => {
    if (!selected) return;
    try {
      const res = await axios.post("http://localhost:5000/api/fees/student", {
        admissionNo: selected.admissionNo,
        feeOverrides: overrides,
      });
      if (res.data.success) toast.success("Fee overrides updated!");
      else toast.error(res.data.error || "Update failed");
    } catch (err) {
      console.error(err);
      toast.error("Failed to save changes");
    }
  };

  return (
    <div className="admin-fees-page">
      <Toaster />
      <h2>🎓 Manage Student Fees</h2>
      <p>View and edit fee overrides for individual students.</p>

      <div className="admin-fee-grid">
        <div className="student-list">
          <h3>All Students</h3>
          {students.length === 0 && <p>No admissions found.</p>}
          <ul>
            {students.map((stu) => (
              <li
                key={stu._id}
                onClick={() => selectStudent(stu)}
                className={selected?._id === stu._id ? "selected" : ""}
              >
                <b>{stu.studentName}</b> ({stu.admissionNo}) - {stu.classApplied}
              </li>
            ))}
          </ul>
        </div>

        <div className="fee-editor">
          {!selected ? (
            <p>Select a student to edit their fee structure.</p>
          ) : (
            <>
              <h3>Edit Fees for: {selected.studentName}</h3>
              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Fee Type</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(overrides).map(([key, val]) => (
                    <tr key={key}>
                      <td>{key}</td>
                      <td>
                        <input
                          type="number"
                          value={val}
                          onChange={(e) => updateOverride(key, e.target.value)}
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <button onClick={saveChanges}>💾 Save Changes</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
